import { categories } from './data.js';
import { api } from './api.js';
const $=(selector,root=document)=>root.querySelector(selector);
const esc=(value='')=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={
search:'<circle cx="10.8" cy="10.8" r="6.7"/><path d="m16 16 4.5 4.5"/>',heart:'<path d="M20.8 4.7a5.4 5.4 0 0 0-7.7 0L12 5.8l-1.1-1.1a5.4 5.4 0 0 0-7.7 7.7L12 21l8.8-8.6a5.4 5.4 0 0 0 0-7.7Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m8 4 8 8-8 8"/>',down:'<path d="m6 9 6 6 6-6"/>',home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',check:'<path d="m5 12 4 4L19 6"/>',filter:'<path d="M4 7h16M7 12h10M10 17h4"/>',leaf:'<path d="M20 3C10 2 2 6 4 15c2 8 17 8 16-12ZM4 21l11-12"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',bag:'<path d="M4 7h16l1 14H3ZM8 8V6a4 4 0 0 1 8 0v2"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z"/>',refresh:'<path d="M20 7A9 9 0 1 0 21 15M20 2v6h-6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',fan:'<circle cx="12" cy="9" r="7"/><circle cx="12" cy="9" r="1"/><path d="M12 16v5M7 22h10M12 8c-7-5-6 5-1 2m2-1c7-5-4-7-2-1m1 2c0 8 8 0 1-1"/>',bike:'<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-10h5l4 10M8 12h9M8 7H5m7-4h5l2 4"/>',cup:'<path d="M4 8h13v8a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5ZM17 8h2a3 3 0 0 1 0 6h-2M7 2v3m5-3v3"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.bag}</svg>`;
const money=value=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const defaults=()=>({query:'',category:'all',campus:'',condition:'',cheap:false,fresh:false,graduation:false,sort:'newest'});
const state={session:null,sessionError:'',filters:defaults(),home:{items:[],total:0,counts:{},page:0,hasMore:false,loading:false,error:''},published:[],favorites:[],favoriteIds:new Set(),favoritesError:'',detail:null,draft:null,profileError:'',tab:'published'};
let routeVersion=0,toastTimer,modalFocus,currentRoute='',homeRequest=0,modalVersion=0,submitting=false,uploading=false,signingOut=false,emailAttempt=0,loginTicker;
const pendingFavorite=new Set(),statusBusy=new Set(),app=$('#app');
function routeInfo(){const[path,search='']=(location.hash.slice(1)||'/').split('?');return{path,params:new URLSearchParams(search)};}
function decodeId(value){try{return decodeURIComponent(value);}catch{return '';}}
function navigate(route){if(submitting||uploading){toast('正在保存或处理照片，请稍等一下。');return;}closeModal();if(location.hash===`#${route}`)loadRoute();else location.hash=route;}
function signedIn(){return !state.identityUnconfirmed&&state.session?.authentication?.provider==='school_email'&&state.session?.user?.emailVerified===true;}
function safeReturnTo(value='/#/') {
  if(typeof value!=='string'||!value.startsWith('/')||value.startsWith('//')||/[\\\u0000-\u001f\u007f]/.test(value))return '/#/';
  let url;try{url=new URL(value,location.origin);}catch{return '/#/';}
  if(url.origin!==location.origin||url.pathname!=='/'||url.search)return '/#/';
  if(!url.hash)return '/#/';
  const path=url.hash.slice(1).split('?')[0];
  if(!['/','/publish','/profile'].includes(path)&&!/^\/product\/[A-Za-z0-9_-]+$/.test(path))return '/#/';
  return `/${url.hash}`;
}
function currentReturnTo(){const{path,params}=routeInfo();return safeReturnTo(path==='/login'?params.get('return_to'):`/${location.hash||'#/'}`);}
function loginPath(returnTo=currentReturnTo()){return `#/login?return_to=${encodeURIComponent(safeReturnTo(returnTo))}`;}
function authentication(){return{provider:signedIn()?'school_email':'guest',configured:state.session?.authentication?.email?.configured===true};}
function accountLabel(){return signedIn()?'学校邮箱账号':'访客';}
function loginLink(label='学校邮箱 / 访客登录',returnTo=currentReturnTo()){return `<a class="button primary" href="${esc(loginPath(returnTo))}">${icon('user')}${esc(label)}${icon('arrow')}</a>`;}
function developmentNotice(){return state.session?.development?'<div class="development-notice" role="status">本地开发预览 · 数据仅保存在本地预览存储，不会同步到正式站点。邮箱登录仍需真实验证。</div>':'';}
function hasUnsavedDraft(){return Boolean(state.draft&&(state.draft.images.length||Object.entries(state.draft.fields).some(([key,value])=>['title','description','seller','contactValue','location'].includes(key)&&String(value).trim())));}
function blankEmailLogin(){return{email:'',code:'',challengeId:'',challengeEmail:'',requestEmail:'',emailMasked:'',expiresAt:0,retryAt:0,retryEmail:'',sending:false,verifying:false,verifiedPending:false,priorUserId:null,returnTo:'/#/',error:'',notice:''};}
state.emailLogin=blankEmailLogin();state.guestError='';
function normalizeSchoolEmail(value){return String(value||'').trim().toLowerCase();}
function validSchoolEmail(value){const email=normalizeSchoolEmail(value),parts=email.split('@');return parts.length===2&&parts[1]==='student.xjtlu.edu.cn'&&parts[0].length>=1&&parts[0].length<=64&&/^[a-z0-9_%+-]+(?:\.[a-z0-9_%+-]+)*$/.test(parts[0]);}
function retrySeconds(){const e=state.emailLogin;return e.retryEmail===normalizeSchoolEmail(e.email)?Math.max(0,Math.ceil((e.retryAt-Date.now())/1000)):0;}
function challengeActive(){const e=state.emailLogin;return Boolean(e.challengeId&&e.challengeEmail===normalizeSchoolEmail(e.email)&&e.expiresAt>Date.now());}
function clearChallenge(){const e=state.emailLogin;Object.assign(e,{code:'',challengeId:'',challengeEmail:'',emailMasked:'',expiresAt:0,verifiedPending:false,notice:''});}
function setLoginEmail(value){const e=state.emailLogin,normalized=normalizeSchoolEmail(value),bound=e.challengeEmail||e.requestEmail;e.email=value;if(bound&&normalized!==bound){emailAttempt++;clearChallenge();Object.assign(e,{retryAt:0,retryEmail:'',requestEmail:'',error:''});}refreshLoginControls();}
function stopLoginTimer(){if(loginTicker){clearInterval(loginTicker);loginTicker=null;}}
function startLoginTimer(){stopLoginTimer();if(routeInfo().path==='/login')loginTicker=setInterval(()=>{if(routeInfo().path!=='/login')stopLoginTimer();else refreshLoginControls();},1000);}
function refreshLoginControls(){
  if(routeInfo().path!=='/login')return;const e=state.emailLogin,seconds=retrySeconds(),configured=authentication().configured;
  const send=$('#send-email-button');if(send){send.disabled=!configured||e.sending||e.verifying||signingOut||seconds>0;send.textContent=e.sending?'正在发送…':seconds>0?`${seconds} 秒后重发`:e.challengeId?'重新发送验证码':'发送验证码';}
  const verify=$('#verify-email-button');if(verify){verify.disabled=!configured||e.sending||e.verifying||signingOut||(!e.verifiedPending&&(!challengeActive()||!/^\d{6}$/.test(e.code)));verify.textContent=e.verifying?'正在确认登录…':e.verifiedPending?'重新确认登录状态':'验证并登录';}
  const email=$('#school-email');if(email)email.disabled=e.verifying||signingOut;
  const code=$('#school-code');if(code){code.disabled=!challengeActive()||e.sending||e.verifying||e.verifiedPending||signingOut;if(code.value!==e.code)code.value=e.code;}
  const feedback=$('#email-feedback');if(feedback)feedback.innerHTML=`${e.error?`<p class="email-error" role="alert">${esc(e.error)}</p>`:''}${e.notice?`<p class="email-success" role="status">${esc(e.notice)}</p>`:''}`;
  const deadline=$('#code-deadline');if(deadline){const remaining=Math.max(0,Math.ceil((e.expiresAt-Date.now())/1000));deadline.textContent=e.challengeId?(remaining>0?`验证码剩余 ${Math.floor(remaining/60)} 分 ${remaining%60} 秒，最多尝试 5 次。`:'验证码已过期，请重新发送。'):'验证码有效期为 10 分钟，最多尝试 5 次；达到上限需重新发送。';}
  const guest=$('[data-action="guest"]');if(guest)guest.disabled=e.verifying||signingOut;
}
function renderLogin(){if(routeInfo().path==='/login'){shell(loginPage(routeInfo().params));refreshLoginControls();startLoginTimer();}}
function loginPage(params){
  const returnTo=safeReturnTo(params.get('return_to')||'/#/'),e=state.emailLogin,configured=authentication().configured;
  return `<section class="login-page school-login-page"><div class="login-intro"><span class="eyebrow">A LITTLE HELLO, A NEW STORY</span><h1>欢迎回来，橘子同学 <span>🍊</span></h1><p>用学校邮箱验证登录，或以访客身份先逛逛。</p></div>
    ${hasUnsavedDraft()?`<div class="login-draft-warning"><strong>你的发布草稿仍留在当前页面</strong><p>学校邮箱验证不会刷新页面。同一账号登录可继续编辑；若切换其他账号或进入访客模式，旧账号草稿会被清除。</p><a class="text-button" href="${esc(returnTo.slice(1))}">返回原页面 ${icon('arrow')}</a></div>`:''}
    ${signedIn()?`<div class="login-current-account"><span class="profile-avatar">🍊</span><div><strong>学校邮箱已验证</strong><p>${esc(state.session.user.emailMasked||'学校邮箱账号')} · 未核验在读学籍</p></div><a class="button secondary small" href="${esc(returnTo.slice(1))}">返回继续</a><button class="text-button" data-action="logout">退出登录</button></div>`:''}
    <div class="school-login-layout"><section class="login-panel email-login-panel"><div class="login-panel-heading"><h2>学校邮箱验证码</h2><span class="badge ${configured?'mint':''}">${configured?'邮箱验证':'邮件服务未开通'}</span></div><p class="email-panel-copy">仅限 <strong>@student.xjtlu.edu.cn</strong> 学生邮箱。</p>
    ${!configured?'<div class="email-unavailable" role="status">验证码邮件服务尚未开通，暂不能发送。你仍可填写邮箱，或先以访客身份浏览。</div>':''}
    <form id="school-login-form"><div class="form-field"><label for="school-email">学校邮箱</label><input id="school-email" name="email" type="email" required maxlength="254" value="${esc(e.email)}" placeholder="Example.Student23@student.xjtlu.edu.cn" autocomplete="email" autocapitalize="none" spellcheck="false" inputmode="email"><span class="field-hint">请使用你能够接收邮件的学校邮箱。</span></div><button id="send-email-button" class="button secondary email-send-button" type="button" data-action="send-email" ${!configured?'disabled':''}>发送验证码</button><div class="form-field"><label for="school-code">6 位验证码</label><input id="school-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" value="${esc(e.code)}" placeholder="输入邮件中的 6 位数字" aria-describedby="code-deadline" required ${!challengeActive()?'disabled':''}><p id="code-deadline" class="field-hint">验证码有效期为 10 分钟，最多尝试 5 次；达到上限需重新发送。</p></div><div id="email-feedback" aria-live="polite"></div><button id="verify-email-button" class="button primary" type="submit" disabled>验证并登录</button></form></section>
    <section class="login-panel guest-login-panel"><span class="guest-illustration" aria-hidden="true">🌿</span><h2>访客登录</h2><p>不用填写资料，先发现校园里的好物。</p><ul><li>浏览公开商品与照片</li><li>使用搜索与筛选</li><li>发布、收藏、查看联系方式需邮箱验证登录</li></ul>${signedIn()?'<p class="guest-account-note">以访客进入会退出当前学校邮箱账号。</p>':''}${state.guestError?`<p class="email-error" role="alert">${esc(state.guestError)}</p>`:''}<button class="button secondary" data-action="guest">以访客身份浏览 ${icon('arrow')}</button></section></div>
    <p class="login-identity-note">${icon('shield')}学校邮箱验证只确认邮箱控制权，不等于在读学籍认证。</p></section>`;
}
async function sendEmailCode(){
  const e=state.emailLogin;if(e.sending||e.verifying||signingOut)return;
  const email=normalizeSchoolEmail($('#school-email')?.value??e.email);e.email=email;e.error='';e.notice='';
  if(!validSchoolEmail(email)){e.error='请填写有效的 @student.xjtlu.edu.cn 学校邮箱；邮箱名称不能以点开头、结尾或包含连续点。';refreshLoginControls();return;}
  if(!authentication().configured){e.error='验证码邮件服务尚未开通，暂不能发送。请先以访客身份浏览。';refreshLoginControls();return;}
  if(retrySeconds()>0){refreshLoginControls();return;}
  const token=++emailAttempt;e.sending=true;e.requestEmail=email;refreshLoginControls();
  try{
    const result=await api.sendEmail(email);
    if(token!==emailAttempt||normalizeSchoolEmail(e.email)!==email)return;
    if(typeof result.challengeId!=='string'||!result.challengeId||!Number.isFinite(result.expiresIn)||result.expiresIn<=0||!Number.isFinite(result.retryAfter)||result.retryAfter<0||typeof result.emailMasked!=='string')throw new Error('未能确认验证码发送结果，请稍后重试。');
    Object.assign(e,{challengeId:result.challengeId,challengeEmail:email,code:'',emailMasked:result.emailMasked,expiresAt:Date.now()+Math.min(result.expiresIn,600)*1000,retryAt:Date.now()+result.retryAfter*1000,retryEmail:email,verifiedPending:false,notice:`验证码已发送至 ${result.emailMasked}，请查收邮件。`});
  }catch(error){if(token===emailAttempt){e.error=message(error);if(error.status===429&&error.retryAfter>0){e.retryAt=Date.now()+error.retryAfter*1000;e.retryEmail=email;}}}
  finally{if(e===state.emailLogin)e.sending=false;renderLogin();}
}
function clearPersonalState(clearDraft=false){state.published=[];state.favorites=[];state.favoriteIds=new Set();state.favoritesError='';state.profileError='';state.detail=null;state.home.items=[];state.home.page=0;if(clearDraft&&state.draft){revokeDraft(state.draft);state.draft=null;}}
async function finishEmailLogin(){
  const e=state.emailLogin,session=await api.session();
  if(session.authentication?.provider!=='school_email'||session.user?.emailVerified!==true)throw new Error('验证码已验证，但尚未确认登录状态，请点击“重新确认登录状态”。');
  const changed=Boolean(e.priorUserId&&e.priorUserId!==session.user.id),returnTo=e.returnTo;
  clearPersonalState(changed);state.session=session;state.sessionError='';state.identityUnconfirmed=false;
  try{const result=await api.favorites();state.favorites=result.items;state.favoriteIds=new Set(result.items.map(p=>p.id));}catch(error){state.favoritesError=message(error);}
  emailAttempt++;state.emailLogin=blankEmailLogin();stopLoginTimer();toast(changed?'学校邮箱登录成功，已清除旧账号的草稿。':'学校邮箱登录成功。');navigate(safeReturnTo(returnTo).slice(2));
}
async function verifyEmailCode(){
  const e=state.emailLogin;if(e.sending||e.verifying||signingOut)return;e.error='';
  if(!e.verifiedPending&&(!challengeActive()||!/^\d{6}$/.test(e.code))){e.error='请先发送验证码，并填写有效期内的 6 位数字验证码。';refreshLoginControls();return;}
  e.verifying=true;refreshLoginControls();
  try{
    if(!e.verifiedPending){e.priorUserId=state.identityUnconfirmed?e.priorUserId:signedIn()?state.session.user.id:null;e.returnTo=currentReturnTo();const result=await api.verifyEmail({email:e.challengeEmail,challengeId:e.challengeId,code:e.code});if(result.ok!==true)throw new Error('服务器未确认验证码验证成功，请重试。');e.verifiedPending=true;state.identityUnconfirmed=true;e.code='';}
    await finishEmailLogin();
  }catch(error){if(e===state.emailLogin){e.error=message(error);e.code='';if(['CODE_EXPIRED','CODE_ATTEMPTS_EXCEEDED'].includes(error.code)){clearChallenge();e.error=message(error);}if(error.status===429&&error.retryAfter>0){e.retryAt=Date.now()+error.retryAfter*1000;e.retryEmail=normalizeSchoolEmail(e.email);}}}
  finally{if(e===state.emailLogin)e.verifying=false;renderLogin();}
}
function confirmLogout(){showModal(`<span class="modal-emoji">🌿</span><h2>要退出当前账号吗？</h2><p>退出后将以访客身份浏览，发布、收藏与联系方式需要学校邮箱验证登录。</p>${hasUnsavedDraft()?'<p class="logout-draft-warning">退出会清除当前未保存的表单和照片，请先保留内容。</p>':''}<div class="modal-actions"><button class="button secondary" data-action="close-modal">继续逛逛</button><button class="button primary" data-action="confirm-logout">确认退出</button></div>`,'确认退出登录');}
async function becomeGuest(kind='guest',confirmed=false){
  if(signingOut||state.emailLogin.verifying)return;
  if(kind==='guest'&&hasUnsavedDraft()&&!confirmed){showModal('<span class="modal-emoji">🌿</span><h2>以访客身份继续吗？</h2><p>这会退出当前账号，并清除未保存的表单和照片。已发布的商品与收藏仍保留在原账号。</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">返回保留内容</button><button class="button primary" data-action="confirm-guest">清除草稿，进入访客</button></div>','确认访客浏览');return;}
  signingOut=true;state.guestError='';refreshLoginControls();let cleared=false;
  try{
    const result=await(kind==='logout'?api.logout():api.guest());if(result.ok!==true)throw new Error('服务器未确认会话已清除，请重新尝试。');cleared=true;
    const session=await api.session();if(session.user!==null||session.authentication?.provider!=='guest')throw new Error('尚未确认访客状态，请重新尝试。');
    clearPersonalState(true);state.session=session;state.sessionError='';state.identityUnconfirmed=false;emailAttempt++;state.emailLogin=blankEmailLogin();stopLoginTimer();closeModal();signingOut=false;navigate('/');toast(kind==='logout'?'已退出，正在以访客身份浏览。':'正在以访客身份浏览。');
  }catch(error){
    if(cleared){clearPersonalState(true);state.session=null;state.sessionError='会话清除后暂时无法确认登录状态，请重新加载。';closeModal();shell(errorView(state.sessionError,'retry-session'));}
    else if(kind==='logout')showModal(`<h2>尚未完成退出</h2><p role="alert">${esc(message(error))}</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">返回</button><button class="button primary" data-action="confirm-logout">重试退出</button></div>`,'退出未完成');
    else{state.guestError=message(error);closeModal();renderLogin();}
  }finally{signingOut=false;refreshLoginControls();}
}
async function logout(){return becomeGuest('logout',true);}
function toast(copy){const target=$('#toast');target.textContent=copy;target.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>target.classList.remove('visible'),3600);}
function message(error){return error?.message||'暂时没有完成，请稍后重试。';}
function timeAgo(value){const date=typeof value==='number'?value:Date.parse(value);if(!Number.isFinite(date))return'最近发布';const hours=Math.max(0,Math.floor((Date.now()-date)/3600000));return hours<1?'刚刚发布':hours<24?`${hours} 小时前`:hours<48?'昨天发布':`${Math.floor(hours/24)} 天前`;}
function categoryName(id){return categories.find(c=>c.id===id)?.name||'生活用品';}
function imageUrl(value){return typeof value==='string'&&value.startsWith('/api/media/')?value:'';}
function productImage(p,index=0){return imageUrl(p.images?.[index]);}
function photoMarkup(p,className='card-image'){const src=productImage(p);return src?`<img class="${className}" src="${esc(src)}" alt="${esc(p.title)}" loading="lazy">`:`<div class="missing-photo" role="img" aria-label="商品照片暂不可用">${icon('bag')}<span>照片暂不可用</span></div>`;}
function empty(title,copy,action=''){return`<div class="empty-state"><span class="empty-emoji">🍊</span><h2>${title}</h2><p>${copy}</p>${action}</div>`;}
function loading(copy='好物正在集合…'){return`<div class="loading-state" role="status"><span class="loading-spinner" aria-hidden="true"></span><p>${copy}</p></div>`;}
function errorView(copy,retry='retry-route'){return`<div class="error-state" role="alert"><strong>暂时没有连接上</strong><p>${esc(copy)}</p><button class="button secondary small" data-action="${retry}">${icon('refresh')}重新加载</button></div>`;}
function authGate(title='先登录，开启你的校园小集市'){return`<section class="auth-gate"><span class="empty-emoji">🍊</span><span class="eyebrow">YOUR CAMPUS CORNER</span><h1>${title}</h1><p>学校邮箱验证登录后可发布、收藏和查看联系方式，访客仅可浏览公开商品。</p>${loginLink()}<small>学校邮箱验证仅确认邮箱控制权，不等于在读学籍认证。</small><a class="text-button" href="#/">先逛逛公开好物 ${icon('arrow')}</a></section>`;}
function header(){return`<a class="skip-link" href="#main-content">跳到主要内容</a><div class="demo-strip live-strip"><span>${icon('sun')}一点闲置，一点新的可能。</span><span>西交利物浦大学 · SIP / 太仓 <span class="demo-dot"></span> 闲置好物，共享发现</span></div><header class="site-header"><div class="container header-inner"><a class="brand" href="#/" aria-label="橘子集首页"><img src="/assets/orange.svg" width="42" height="42" alt=""><span>橘子集<small>JUZI CAMPUS</small></span></a><button class="location-button" data-action="campus">${icon('pin')}<span>西交利物浦大学<small>${esc(state.filters.campus||'全部校区')}</small></span>${icon('down')}</button><form class="search-form" role="search"><label class="sr-only" for="global-search">搜索校园闲置</label>${icon('search')}<input id="global-search" name="query" placeholder="搜搜好物，让心动有回音" value="${esc(state.filters.query)}" autocomplete="off"><button type="submit">搜索</button></form><div class="header-actions"><a class="header-favorite" href="#/profile?tab=favorites">${icon('heart')}<span>我的收藏</span></a><a class="button primary" href="#/publish">${icon('plus')}<span>发布闲置</span></a><a class="header-avatar" href="#/profile" aria-label="${signedIn()?'个人中心':'登录与个人中心'}">🍊</a></div></div></header>`;}
function footer(){return`<footer class="site-footer container"><div><a class="brand" href="#/"><img src="/assets/orange.svg" alt="" width="32" height="32"><span>橘子集</span></a><p>让每一件好物，都有下一段校园故事。</p></div><div class="footer-links"><span>校园发现 · 友好面交 · 循环生活</span><button class="text-button" data-action="about">关于橘子集</button><button class="text-button" data-action="privacy">隐私与联系</button>${signedIn()?'<button class="text-button" data-action="logout">退出登录</button>':`<a href="${esc(loginPath())}">登录</a>`}</div><p class="footer-note">商品与照片公开展示，联系方式仅登录后可见。学校邮箱验证不等于在读学籍核验；面交前请自行核实。</p></footer>`;}
function mobileNav(path){const profile=path==='/profile',publish=path==='/publish';return`<nav class="mobile-nav" aria-label="手机导航"><a href="#/" class="${path==='/'?'active':''}">${icon('home')}<span>逛一逛</span></a><a href="#/profile?tab=favorites" class="${profile&&state.tab==='favorites'?'active':''}">${icon('heart')}<span>收藏</span></a><a href="#/publish" class="mobile-publish ${publish?'active':''}">${icon('plus')}<span>发布</span></a><a href="#/profile" class="${profile&&state.tab!=='favorites'?'active':''}">${icon('user')}<span>我的</span></a></nav>`;}
function shell(content){const{path}=routeInfo();document.body.className=path.startsWith('/product/')?'page-detail':path==='/publish'?'page-publish':path==='/profile'?'page-profile':path==='/login'?'page-login':'page-home';document.title=`${path==='/'?'校园好物，快乐接力':path==='/publish'?'发布闲置':path==='/profile'?'我的小角落':path==='/login'?'选择登录方式':'好物详情'} · 橘子集`;app.innerHTML=developmentNotice()+header()+`<main class="container" id="main-content" tabindex="-1">${content}</main>`+footer()+mobileNav(path);}
function card(p,{manage=false}={}){const liked=state.favoriteIds.has(p.id),inactive=p.status!=='active';return`<article class="product-card ${inactive?'is-inactive':''}" data-product-id="${esc(p.id)}"><div class="image-wrap"><a href="#/product/${encodeURIComponent(p.id)}" tabindex="-1" aria-hidden="true">${photoMarkup(p)}</a>${p.graduation?'<span class="image-badge">🎓 毕业转让</span>':''}<button class="favorite-button ${liked?'is-favorite':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="${liked?'取消收藏':'收藏'}${esc(p.title)}" aria-pressed="${liked}">${icon('heart')}</button>${inactive?'<span class="inactive-label">已下架</span>':''}</div><div class="product-body"><div class="card-tags"><span class="condition-tag">${esc(p.condition)}</span><span class="campus-tag">${esc(p.campus)}</span></div><h3 class="product-title"><a href="#/product/${encodeURIComponent(p.id)}">${esc(p.title)}</a></h3><div class="price-row"><span class="price"><small>¥</small>${money(p.price)}</span>${Number(p.originalPrice)>0?`<span class="old-price">¥${money(p.originalPrice)}</span>`:''}</div><div class="seller-line"><span><span class="seller-avatar">🍊</span>${esc(p.seller)}</span><time>${timeAgo(p.createdAt)}</time></div>${manage?`<div class="manage-actions"><a class="button secondary small" href="#/publish?edit=${encodeURIComponent(p.id)}">${icon('edit')}编辑</a><button class="button ghost small" data-action="status" data-id="${esc(p.id)}" ${statusBusy.has(p.id)?'disabled':''}>${inactive?'重新上架':'下架'}</button></div>`:''}</div></article>`;}
function chips(){return[['cheap','💰','百元以内'],['fresh','✨','几乎全新'],['graduation','🎓','毕业转让']].map(([id,emoji,label])=>`<button class="chip ${state.filters[id]?'active':''}" data-action="chip" data-filter="${id}" aria-pressed="${state.filters[id]}">${emoji} ${label}${state.filters[id]?icon('check'):''}</button>`).join('');}
function campusOptions(selected='',all=false){return`${all?'<option value="">全部校区</option>':''}${['SIP 校区','太仓校区'].map(c=>`<option ${selected===c?'selected':''}>${c}</option>`).join('')}`;}
function conditionOptions(selected='',all=false){return`${all?'<option value="">不限成色</option>':''}${['几乎全新','九成新','八成新'].map(c=>`<option ${selected===c?'selected':''}>${c}</option>`).join('')}`;}
function home(){const f=state.filters,h=state.home;return`<section class="home-hero" aria-labelledby="hero-title"><div class="hero-copy"><span class="eyebrow"><span></span>校园好物 · 快乐接力</span><h1 class="hero-title" id="hero-title">闲置转个弯，<br>好物<span>遇同学<svg viewBox="0 0 200 16" aria-hidden="true"><path d="M4 10Q95 0 195 9" fill="none" stroke="currentColor" stroke-width="8" stroke-linecap="round"/></svg></span></h1><p class="hero-subtitle">用不上的闲置，刚刚好的心动。<br>给好物一个新的校园故事。</p><div class="hero-actions"><a class="button primary" href="#/publish">${icon('plus')}让闲置发光${icon('arrow')}</a><a class="hero-secondary" href="#discover">先逛逛好物 ${icon('down')}</a></div><div class="hero-trust"><span>${icon('pin')}线下面交</span><span>${icon('leaf')}循环生活</span><span>✦ 闲置也可爱</span></div></div><div class="hero-art"><img src="/assets/hero.svg" alt="橘子同学、小风扇和电瓶车的校园生活插画" width="600" height="400"><span class="floating-sticker sticker-top">旧物新生，快乐加倍 ✨</span><span class="floating-sticker sticker-bottom">HELLO, NEW STORY!</span></div></section><section class="category-section" aria-label="好物分类"><div class="category-grid">${categories.filter(c=>c.id!=='all').map(c=>`<button class="category-card ${f.category===c.id?'selected':''}" data-action="category" data-category="${esc(c.id)}" aria-pressed="${f.category===c.id}"><span class="cat-icon">${icon(c.id==='appliance'?'fan':c.id==='ebike'?'bike':'cup')}</span><span class="cat-copy"><strong>${esc(c.name)}</strong><small>${esc(c.subtitle)}</small></span><span class="category-count">${h.loading&&!h.page?'发现好物':`${Number(h.counts[c.id]||0)} 件好物`} ${icon('arrow')}</span></button>`).join('')}</div></section><section id="discover" class="discover-section" aria-labelledby="discover-title"><div class="section-head"><div><span class="section-eyebrow">GOOD FINDS, GOOD VIBES</span><h2 id="discover-title">今天，也有好物在等你<span>✦</span></h2></div><span class="section-note">淘一点喜欢，省一点生活费。</span></div><div class="discover-layout"><aside class="filters-sidebar"><div class="sidebar-title">${icon('filter')}挑挑你的心头好</div><h3>好物分类</h3><div class="sidebar-categories">${categories.map(c=>`<button class="sidebar-category ${f.category===c.id?'active':''}" data-action="category" data-category="${esc(c.id)}"><span>${esc(c.id==='all'?'所有闲置':c.name)}</span><span>${Number(h.counts[c.id]||0)}</span></button>`).join('')}</div><label for="campus-filter">交易校区</label><select id="campus-filter" data-filter="campus">${campusOptions(f.campus,true)}</select><label for="condition-filter">商品成色</label><select id="condition-filter" data-filter="condition">${conditionOptions(f.condition,true)}</select><div class="sidebar-note">🍊<strong>好物不闲着</strong><p>用一次小小的转让，<br>接住下一份喜欢。</p></div></aside><div class="catalog"><div class="filter-row">${chips()}<button class="text-button clear-filter" data-action="clear-filters">重置筛选</button></div><div class="results-toolbar"><p>${f.query?`“${esc(f.query)}” · `:''}${h.loading&&!h.page?'正在发现好物…':`发现 <strong>${h.total}</strong> 件${f.category==='all'?'校园好物':esc(categoryName(f.category))}`}</p><label class="sort-label">排序<select class="sort-select" data-filter="sort" aria-label="商品排序">${[['newest','最新发布'],['price-asc','价格从低到高'],['price-desc','价格从高到低']].map(([v,t])=>`<option value="${v}" ${v===f.sort?'selected':''}>${t}</option>`).join('')}</select></label><button class="mobile-filter-button icon-button" data-action="mobile-filters" aria-label="校区和成色筛选">${icon('filter')}</button></div>${h.error?errorView(h.error,'retry-home'):''}${h.loading&&!h.page?loading():h.items.length?`<div class="product-grid">${h.items.map(p=>card(p)).join('')}</div>${h.hasMore?`<button class="button secondary load-more" data-action="load-more" ${h.loading?'disabled':''}>${h.loading?'正在加载…':'再发现一些好物'} ${icon('down')}</button>`:`<div class="catalog-end"><span>🍊</span>已展示全部 ${h.total} 件好物。</div>`}`:h.error?'':empty('第一份心动，等你开启',f.query||f.category!=='all'||f.campus||f.condition||f.cheap||f.fresh||f.graduation?'暂时没有符合筛选的商品，换个条件试试。':'集市刚刚开张。发布一件闲置，让好物从这里接力。',`<a class="button primary" href="#/publish">发布第一件闲置 ${icon('arrow')}</a>`)}</div></div></section>`;}
async function loadHome(more=false,version=routeVersion){if(more&&(state.home.loading||!state.home.hasMore))return;const requestId=++homeRequest,page=more?state.home.page+1:1,filters={...state.filters};if(!more)state.home={items:[],total:0,counts:state.home.counts,page:0,hasMore:false,loading:true,error:''};else Object.assign(state.home,{loading:true,error:''});if(routeInfo().path==='/')shell(home());try{const result=await api.products(filters,page);if(requestId!==homeRequest||version!==routeVersion)return;const items=Array.isArray(result.items)?result.items:[],merged=more?[...state.home.items,...items]:items;state.home={items:[...new Map(merged.map(p=>[p.id,p])).values()],total:Number(result.total||0),counts:result.categoryCounts||{},page:Number(result.page||page),hasMore:Boolean(result.hasMore),loading:false,error:''};}catch(error){if(requestId!==homeRequest||version!==routeVersion)return;Object.assign(state.home,{loading:false,error:message(error)});}if(version===routeVersion&&routeInfo().path==='/')shell(home());}
function detail(p){const liked=state.favoriteIds.has(p.id),active=p.status==='active',src=productImage(p);return`<nav class="breadcrumbs" aria-label="面包屑"><a href="#/">首页</a>${icon('chevron')}<a href="#/" data-action="category" data-category="${esc(p.category)}">${esc(categoryName(p.category))}</a>${icon('chevron')}<span>好物详情</span></nav><section class="detail-layout"><div class="detail-gallery">${src?`<img class="main-product-image" src="${esc(src)}" alt="${esc(p.title)}" id="detail-photo" width="800" height="640">`:`<div class="main-product-image">${photoMarkup(p)}</div>`}<div class="thumb-row">${(p.images||[]).map((value,index)=>{const url=imageUrl(value);return url?`<button class="thumbnail ${index===0?'selected':''}" data-action="photo" data-src="${esc(url)}" aria-label="查看第 ${index+1} 张照片" aria-pressed="${index===0}"><img src="${esc(url)}" alt="商品照片 ${index+1}"></button>`:'';}).join('')}</div><p class="photo-note">照片由卖家上传 · 面交时请现场确认实物</p></div><div class="detail-info"><div class="detail-tags"><span class="badge mint">${esc(categoryName(p.category))}</span><span class="badge">${esc(p.condition)}</span>${p.graduation?'<span class="badge">🎓 毕业转让</span>':''}${!active?'<span class="badge">已下架</span>':''}</div><h1>${esc(p.title)}</h1><p class="detail-subtitle">喜欢的好物，值得再被喜欢一次。</p><div class="detail-price"><span class="price"><small>¥</small>${money(p.price)}</span>${Number(p.originalPrice)>0?`<span class="old-price">购入价 ¥${money(p.originalPrice)}</span>`:''}</div><div class="detail-location">${icon('pin')}<span>西交利物浦大学 · ${esc(p.campus)}<strong>${esc(p.location)}</strong></span><span class="badge mint">线下面交</span></div><dl class="spec-grid">${Object.entries(p.specs||{}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="detail-actions"><button class="button primary" data-action="contact" data-id="${esc(p.id)}" ${!active&&!p.mine?'disabled':''}>${icon('user')}${signedIn()?'联系卖家':'登录后联系'}${icon('arrow')}</button><button class="button secondary ${liked?'is-favorite':''}" data-action="favorite" data-id="${esc(p.id)}" aria-pressed="${liked}">${icon('heart')}${liked?'已收藏':'收藏好物'}</button></div><div class="seller-panel"><span class="profile-avatar">🍊</span><div><strong>${esc(p.seller)}</strong><p>${p.sellerEmailVerified===true?'学校邮箱已验证':'学校邮箱未核验'} · 未核验在读学籍</p></div><span class="muted">${timeAgo(p.createdAt)}</span></div>${p.mine?`<a class="text-button owner-edit" href="#/publish?edit=${encodeURIComponent(p.id)}">${icon('edit')}编辑我的商品</a>`:''}</div></section><section class="detail-description"><h2>关于这件好物 <span>✦</span></h2><p>${esc(p.description).replace(/\n/g,'<br>')}</p><div class="meetup-note">${icon('shield')}平台未核实学生身份。请在校园公共区域面交，核实商品与交易方后再决定。</div></section><div class="sticky-detail-actions"><span class="price"><small>¥</small>${money(p.price)}</span><button class="icon-button ${liked?'is-favorite':''}" data-action="favorite" data-id="${esc(p.id)}" aria-label="${liked?'取消收藏':'收藏商品'}" aria-pressed="${liked}">${icon('heart')}</button><button class="button primary" data-action="contact" data-id="${esc(p.id)}" ${!active&&!p.mine?'disabled':''}>${signedIn()?'联系卖家':'登录后联系'} ${icon('arrow')}</button></div>`;}
function profile(){const products=state.tab==='favorites'?state.favorites:state.published;return`<section class="profile-banner"><span class="profile-avatar">🍊</span><div class="profile-summary"><span class="eyebrow">MY LITTLE CORNER</span><h1>你好，橘子同学！</h1><p>学校邮箱已验证 · 未核验在读学籍</p><p class="profile-masked-email">${esc(state.session.user.emailMasked||'')}</p><span class="badge">发布时自主填写公开昵称</span></div><div class="profile-stats"><div><strong>${state.published.length}</strong><span>我的发布</span></div><div><strong>${state.favorites.length}</strong><span>心动收藏</span></div></div></section><div class="profile-section"><div class="tabs" role="tablist" aria-label="个人商品"><a href="#/profile" role="tab" aria-selected="${state.tab==='published'}" class="${state.tab==='published'?'active':''}">我的发布 <span>${state.published.length}</span></a><a href="#/profile?tab=favorites" role="tab" aria-selected="${state.tab==='favorites'}" class="${state.tab==='favorites'?'active':''}">我的收藏 <span>${state.favorites.length}</span></a></div><div class="profile-notice">${icon('shield')}${state.session?.development?'当前为本地开发预览；发布与收藏保存在本地存储，不会同步到正式站点。':'发布与收藏已保存到你的账号，登录同一账号可在其他设备查看。'}</div>${state.profileError?errorView(state.profileError):products.length?`<div class="product-grid">${products.map(p=>card(p,{manage:state.tab==='published'})).join('')}</div>`:empty(state.tab==='published'?'你的第一件好物，准备好了吗？':'喜欢的好物，都值得被记住',state.tab==='published'?'让闲置继续发光，也给宿舍腾出一点空间。':'逛一逛，点下爱心，把小小的心动收藏起来。',`<a class="button primary" href="${state.tab==='published'?'#/publish':'#/'}">${state.tab==='published'?'发布第一件闲置':'去逛逛好物'}${icon('arrow')}</a>`)}</div>`;}
function newDraft(product=null,contact=null){const category=product?.category||'appliance';return{key:product?.id||'new',id:product?.id||null,fields:{title:product?.title||'',category,price:product?.price??'',originalPrice:product?.originalPrice??'',condition:product?.condition||'几乎全新',campus:product?.campus||'SIP 校区',location:product?.location||'',description:product?.description||'',seller:product?.seller||'',contactType:contact?.type||'wechat',contactValue:contact?.value||'',graduation:Boolean(product?.graduation)},specs:{[category]:{...(product?.specs||{})}},images:(product?.images||[]).map((url,i)=>({url:imageUrl(url),mediaId:product.imageIds?.[i]||null,blob:null})).filter(p=>p.url),error:'',notice:'',consent:false};}
function specLabels(category){return category==='ebike'?['购入时间','电池情况','卖家自述续航']:category==='daily'?['尺寸','数量','使用情况']:['型号','使用情况'];}
function field(label,name,value='',{type='text',required=true,min,max,step,full=false,placeholder='',maxlength=100}={}){return`<div class="form-field ${full?'field-full':''}"><label for="field-${name}">${label}${required?'<span class="required"> *</span>':''}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${step?`step="${step}"`:''} ${type==='text'?`maxlength="${maxlength}"`:''} placeholder="${esc(placeholder)}"></div>`;}
function categoryFields(draft){const category=draft.fields.category,values=draft.specs[category]||{};return specLabels(category).map((label,i)=>field(label,`spec-${i}`,values[label]||'',{placeholder:category==='ebike'&&i===2?'如实填写估计续航，仅供参考':'请如实描述'})).join('');}
function uploadPreview(){return state.draft.images.map((photo,i)=>`<div class="uploaded-item"><img src="${esc(photo.url)}" alt="已选照片 ${i+1}">${i===0?'<span>封面</span>':''}<button type="button" data-action="remove-photo" data-index="${i}" ${submitting||uploading?'disabled':''} aria-label="移除第 ${i+1} 张照片">${icon('close')}</button></div>`).join('');}
function publish(){const d=state.draft,f=d.fields;return`<div class="page-heading"><span class="eyebrow">PASS ON THE GOOD STUFF</span><h1>${d.id?'再打扮一下你的好物':'让闲置，遇见新同学'} <span>✦</span></h1><p>拍张照片，写下它的故事。下一份心动，就从这里开始。</p></div><form id="publish-form"><div class="publish-layout"><section class="upload-panel"><div class="panel-heading"><h2>给好物拍个照</h2><span>最多 6 张</span></div><label class="upload-zone" for="photo-input">${icon('upload')}<strong>点击选择商品照片</strong><span>第一张将成为封面，请勿上传个人证件</span><small>JPG / PNG / WebP，每张不超过 8 MB</small></label><input class="sr-only" id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" multiple><div class="uploaded-grid" id="uploaded-images">${uploadPreview()}</div><p class="field-hint" id="photo-error" role="alert"></p><div class="photo-tips"><strong>🍊 橘子小贴士</strong><p>找个亮一点的地方，拍下正面和细节。<br>发布后的商品照片可被所有访客查看。</p></div></section><section class="form-panel"><h2>说说这件好物</h2><div class="form-grid">${field('商品标题','title',f.title,{full:true,placeholder:'例如：陪我度过夏天的小风扇'})}<div class="form-field field-full"><label for="field-category">好物分类 <span class="required">*</span></label><select id="field-category" name="category">${categories.filter(c=>c.id!=='all').map(c=>`<option value="${esc(c.id)}" ${f.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>${field('转让价格（元）','price',f.price,{type:'number',min:0.01,max:100000,step:'0.01'})}${field('购入价格（元）','originalPrice',f.originalPrice,{type:'number',min:0,max:100000,step:'0.01',required:false})}<div class="form-field"><label for="field-condition">商品成色</label><select id="field-condition" name="condition">${conditionOptions(f.condition)}</select></div><div class="form-field"><label for="field-campus">交易校区</label><select id="field-campus" name="campus">${campusOptions(f.campus)}</select></div>${field('面交地点','location',f.location,{full:true,placeholder:'例如：图书馆正门 / 食堂门口'})}<div class="form-field field-full"><label for="field-description">好物故事 <span class="required">*</span></label><textarea id="field-description" name="description" required minlength="5" maxlength="2000" rows="4" placeholder="买了多久、使用感受、为什么转让，还有需要说明的小细节…">${esc(f.description)}</textarea></div><div id="category-fields" class="form-grid field-full">${categoryFields(d)}</div><label class="checkbox-field field-full"><input name="graduation" type="checkbox" ${f.graduation?'checked':''}>这是一次毕业转让 🎓</label><div class="form-section-title field-full"><h2>让买家找到你</h2><p>昵称公开展示；联系方式仅已登录用户可查看。</p></div>${field('公开展示昵称','seller',f.seller,{full:true,maxlength:30,placeholder:'想让大家怎么称呼你？'})}<div class="form-field"><label for="field-contactType">联系方式</label><select id="field-contactType" name="contactType"><option value="wechat" ${f.contactType==='wechat'?'selected':''}>微信号</option><option value="phone" ${f.contactType==='phone'?'selected':''}>手机号</option></select></div>${field(f.contactType==='phone'?'手机号':'微信号','contactValue',f.contactValue,{maxlength:100,placeholder:'仅登录用户可见'})}<div class="publish-demo-note live-publish-note field-full">${icon('shield')}学校邮箱验证仅确认邮箱控制权。请如实填写商品与联系信息，交易前仍需核实对方身份。</div><label class="checkbox-field consent-field field-full"><input name="consent" type="checkbox" required ${d.consent?'checked':''}>我已确认：商品信息、公开昵称与照片将公开展示，联系方式仅登录用户可见。</label></div></section></div><div id="publish-feedback" role="alert">${d.error?`<div class="error-state">${esc(d.error)}${d.notice?`<p>${esc(d.notice)}</p>`:''}</div>`:''}</div><div class="form-actions"><span>✨ ${state.session?.development?'本地预览数据不会同步到正式站点。':'资料保存在云端，发布成功后可在「我的」管理。'}</span><button class="button secondary" type="button" data-action="preview">预览好物</button><button class="button primary" type="submit">${d.id?'保存修改':'发布我的闲置'}${icon('arrow')}</button></div></form>`;}
function captureDraft(form=$('#publish-form')){if(!form||!state.draft||submitting)return;const d=state.draft,data=new FormData(form),previous=d.fields.category;d.specs[previous]||={};specLabels(previous).forEach((label,i)=>{if(data.has(`spec-${i}`))d.specs[previous][label]=String(data.get(`spec-${i}`));});for(const key of['title','category','price','originalPrice','condition','campus','location','description','seller','contactType','contactValue'])if(data.has(key))d.fields[key]=String(data.get(key));d.fields.graduation=data.get('graduation')==='on';d.consent=data.get('consent')==='on';}
function validateDraft(){const form=$('#publish-form');captureDraft(form);if(!form?.reportValidity())return null;const d=state.draft,f=d.fields;if(uploading){toast('照片正在处理中，请稍等一下。');return null;}if(!d.images.length){$('#photo-error').textContent='请至少添加一张商品照片。';$('#photo-input').focus();return null;}const specs=Object.fromEntries(specLabels(f.category).map(label=>[label,String(d.specs[f.category]?.[label]||'').trim()]));if(!f.title.trim()||f.description.trim().length<5||!f.seller.trim()||!f.location.trim()||!f.contactValue.trim()||Object.values(specs).some(v=>!v)){toast('请填写完整信息，商品描述至少 5 个字。');return null;}if(f.contactType==='phone'&&!/^1[3-9]\d{9}$/.test(f.contactValue.trim())){toast('请填写有效的 11 位中国大陆手机号。');$('#field-contactValue').focus();return null;}return{title:f.title.trim(),category:f.category,price:Number(f.price),originalPrice:Number(f.originalPrice||0),condition:f.condition,campus:f.campus,location:f.location.trim(),description:f.description.trim(),specs,graduation:f.graduation,seller:f.seller.trim(),contactType:f.contactType,contactValue:f.contactValue.trim()};}
function setFormBusy(busy,label='正在保存…'){const form=$('#publish-form');if(!form)return;for(const element of form.elements)element.disabled=busy;const button=$('[type="submit"]',form);if(button)button.innerHTML=busy?esc(label):`${state.draft?.id?'保存修改':'发布我的闲置'}${icon('arrow')}`;}
function publishError(error){const d=state.draft;if(!d)return;d.error=message(error);if(error?.status===401)d.notice='登录已失效，请使用学校邮箱重新验证。站内验证会保留当前草稿；若换用其他账号，旧账号草稿会被清除。';const target=$('#publish-feedback');if(target)target.innerHTML=`<div class="error-state">${esc(d.error)}${d.notice?`<p>${esc(d.notice)}</p>`:''}${error?.status===401?loginLink('学校邮箱重新登录'):''}${d.uncertain?'<div class="uncertain-actions"><a class="button secondary small" href="#/profile">先查看我的发布</a><button type="button" class="button ghost small" data-action="confirm-retry">我已确认未发布，允许重试</button></div>':''}</div>`;target?.scrollIntoView({block:'nearest',behavior:'smooth'});}
async function saveDraft(){if(submitting||uploading)return;if(state.draft?.uncertain){publishError(new Error('上次发布结果尚未确认，请先到「我的发布」核实，避免重复发布。'));return;}const values=validateDraft();if(!values)return;const d=state.draft;submitting=true;d.error='';d.notice='';setFormBusy(true,'正在上传照片…');let succeeded=false,writing=false;try{for(const photo of d.images){if(photo.mediaId)continue;if(!photo.blob)throw new Error('这张照片无法保存，请移除后重新选择。');const result=await api.upload(photo.blob);if(!result.mediaId||!result.url)throw new Error('照片上传结果不完整，请稍后重试。');photo.mediaId=result.mediaId;photo.serverUrl=result.url;}setFormBusy(true,'正在保存好物…');writing=true;const{product}=await api.save(d.id,{...values,imageIds:d.images.map(photo=>photo.mediaId)});if(!product?.id)throw new Error('服务器没有确认保存结果，请到「我的」核实后再尝试。');revokeDraft(d);state.draft=null;state.detail=null;succeeded=true;toast(d.id?'修改已保存':'发布成功！好物已经加入集市。');}catch(error){d.uncertain=writing&&!d.id&&(!error.status||error.status>=500);d.notice=d.uncertain?'未能确认服务器是否已保存。内容仍保留在当前页面，请先查看「我的发布」，确认没有重复商品后再继续。':'填写内容已保留在当前页面，请勿刷新；已上传成功的照片重试时不会重复上传。';publishError(error);}finally{submitting=false;setFormBusy(false);}if(succeeded)navigate('/profile');}
async function compressPhoto(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('请选择 JPG、PNG 或 WebP 照片。');if(file.size>8*1024*1024)throw new Error('单张照片不能超过 8 MB。');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('照片无法读取，请换一张。'));image.src=url;});const scale=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw new Error('浏览器暂时无法处理照片。');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.85));if(!blob)throw new Error('照片处理失败，请换一张。');return{blob,url:URL.createObjectURL(blob),mediaId:null};}finally{URL.revokeObjectURL(url);}}
function revokeDraft(d){for(const photo of d?.images||[])if(photo.url.startsWith('blob:'))URL.revokeObjectURL(photo.url);}
async function selectPhotos(input){if(uploading||submitting||!state.draft)return;captureDraft();const d=state.draft,files=[...input.files],slots=6-d.images.length;if(files.length>slots)toast(`还可以添加 ${slots} 张照片，已取前 ${slots} 张。`);uploading=true;input.disabled=true;const error=$('#photo-error');if(error)error.textContent='正在处理照片…';try{for(const file of files.slice(0,slots)){try{const photo=await compressPhoto(file);if(state.draft===d)d.images.push(photo);else URL.revokeObjectURL(photo.url);}catch(err){toast(message(err));}}}finally{uploading=false;if(input.isConnected){input.disabled=false;input.value='';}if(state.draft===d&&$('#uploaded-images')){$('#uploaded-images').innerHTML=uploadPreview();$('#photo-error').textContent='';}}}
async function loadRoute(){const version=++routeVersion,{path,params}=routeInfo();if(path!=='/login')stopLoginTimer();closeModal();if(currentRoute!==location.hash){window.scrollTo({top:0,behavior:'instant'});currentRoute=location.hash;}if(path==='/profile')state.tab=params.get('tab')==='favorites'?'favorites':'published';if(state.sessionError){shell(errorView(state.sessionError,'retry-session'));return;}if(!state.session){shell(loading('正在连接校园集市…'));return;}if(path==='/'){await loadHome(false,version);return;}if(path==='/login'){renderLogin();return;}if((path==='/publish'||path==='/profile')&&!signedIn()){shell(authGate(path==='/publish'?'登录后，让闲置继续发光':'你的校园小角落，从登录开始'));return;}if(path==='/publish'){const id=params.get('edit'),key=id||'new';if(state.draft?.key===key){shell(publish());return;}if(!id){if(state.draft)revokeDraft(state.draft);state.draft=newDraft();shell(publish());return;}shell(loading('正在取回你的好物…'));try{const[{product},contact]=await Promise.all([api.product(id),api.contact(id)]);if(version!==routeVersion)return;if(!product?.mine)throw new Error('你只能编辑自己发布的商品。');if(state.draft)revokeDraft(state.draft);state.draft=newDraft(product,contact);shell(publish());}catch(error){if(version===routeVersion)shell(errorView(message(error)));}return;}if(path==='/profile'){shell(loading('正在取回你的发布与收藏…'));try{const[mine,favs]=await Promise.all([api.mine(),api.favorites()]);if(version!==routeVersion)return;state.published=mine.items||[];state.favorites=favs.items||[];state.favoriteIds=new Set(state.favorites.map(p=>p.id));state.favoritesError='';state.profileError='';shell(profile());}catch(error){if(version===routeVersion){state.profileError=message(error);shell(profile());}}return;}if(path.startsWith('/product/')){const id=decodeId(path.slice(9));if(!id){shell(empty('这件好物暂时找不到啦','回首页，再发现一点喜欢。','<a class="button primary" href="#/">回到首页</a>'));return;}shell(loading('正在打开这件好物…'));try{const{product}=await api.product(id);if(version!==routeVersion)return;if(!product)throw new Error('这件商品暂时不可查看。');state.detail=product;shell(detail(product));}catch(error){if(version===routeVersion)shell(error.status===404?empty('这件好物暂时找不到啦','它可能已经下架，去发现别的心动吧。','<a class="button primary" href="#/">回到首页</a>'):errorView(message(error)));}return;}shell(empty('这个小角落还没有好物','回首页继续逛逛吧。','<a class="button primary" href="#/">回到首页</a>'));}
async function refreshSession(){state.sessionError='';shell(loading('正在连接校园集市…'));try{const previousId=state.session?.user?.id||state.emailLogin.priorUserId;state.session=await api.session();state.identityUnconfirmed=false;if(previousId&&previousId!==state.session.user?.id)clearPersonalState(true);if(signedIn()){try{const result=await api.favorites();state.favorites=result.items||[];state.favoriteIds=new Set(state.favorites.map(p=>p.id));state.favoritesError='';}catch(error){state.favoritesError=message(error);toast(`收藏暂未加载：${message(error)}`);}}}catch(error){state.sessionError=message(error);state.session=null;}await loadRoute();}
function showModal(content,label='提示'){closeModal();modalFocus=document.activeElement;const version=++modalVersion;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(label)}" tabindex="-1"><button class="modal-close icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button>${content}</section></div>`;document.body.classList.add('modal-open');$('.modal').focus();return version;}
function closeModal(){modalVersion++;const root=$('#modal-root');if(!root?.hasChildNodes())return;root.innerHTML='';document.body.classList.remove('modal-open');if(modalFocus?.isConnected)modalFocus.focus();modalFocus=null;}
function promptLogin(copy='使用学校邮箱验证登录后，可收藏、发布和查看卖家联系方式。'){showModal(`<span class="modal-emoji">🍊</span><h2>把喜欢留在你的账号里</h2><p>${copy}</p><p>访客仅可浏览公开商品；学校邮箱验证不等于在读学籍认证。</p><div class="modal-actions">${loginLink()}</div>`,'学校邮箱与访客登录');}
async function contact(id){if(!signedIn()){promptLogin('登录后可查看卖家填写的联系方式，约好地点再见面。');return;}const version=showModal(loading('正在读取卖家联系方式…'),'联系卖家');try{const result=await api.contact(id);if(version!==modalVersion)return;showModal(`<span class="modal-emoji">🍊</span><span class="eyebrow">SAY HELLO TO A GOOD FIND</span><h2>和好物的主人打个招呼</h2><p>联系方式由卖家填写，请在交易前核实。</p><div class="contact-card"><strong>联系卖家</strong><dl><div><dt>${result.type==='phone'?'手机号':result.type==='qq'?'QQ 号':'微信号'}</dt><dd>${esc(result.value)}</dd></div></dl></div><div class="meetup-note">${icon('shield')}未验证学生身份。请在公共区域面交，现场确认商品情况。</div><div class="modal-actions"><button class="button primary" data-action="close-modal">知道啦 ${icon('check')}</button></div>`,'卖家联系方式');}catch(error){if(version!==modalVersion)return;if(error.status===401){promptLogin();return;}showModal(`<h2>联系方式暂时没有取到</h2><p role="alert">${esc(message(error))}</p><div class="modal-actions"><button class="button secondary" data-action="contact" data-id="${esc(id)}">重新读取</button></div>`,'读取失败');}}
function syncFavoriteButtons(id,liked){for(const button of document.querySelectorAll('[data-action="favorite"]'))if(button.dataset.id===id){button.classList.toggle('is-favorite',liked);button.setAttribute('aria-pressed',String(liked));if(button.classList.contains('button'))button.innerHTML=`${icon('heart')}${liked?'已收藏':'收藏好物'}`;else button.setAttribute('aria-label',liked?'取消收藏':'收藏商品');}}
async function favorite(id){if(!signedIn()){promptLogin();return;}if(pendingFavorite.has(id))return;if(state.favoritesError){try{const result=await api.favorites();state.favorites=result.items||[];state.favoriteIds=new Set(state.favorites.map(p=>p.id));state.favoritesError='';}catch(error){toast(`收藏状态未加载，未修改：${message(error)}`);return;}}const liked=!state.favoriteIds.has(id);pendingFavorite.add(id);const buttons=[...document.querySelectorAll('[data-action="favorite"]')].filter(b=>b.dataset.id===id);buttons.forEach(b=>b.disabled=true);try{await api.favorite(id,liked);if(liked)state.favoriteIds.add(id);else{state.favoriteIds.delete(id);state.favorites=state.favorites.filter(p=>p.id!==id);}syncFavoriteButtons(id,liked);if(routeInfo().path==='/profile')await loadRoute();toast(liked?'已收藏，登录同一账号随时找它 ♥':'已取消收藏');}catch(error){if(error.status===401)promptLogin();else toast(message(error));}finally{pendingFavorite.delete(id);for(const b of buttons)if(b.isConnected)b.disabled=false;}}
async function changeStatus(id){if(statusBusy.has(id))return;const product=state.published.find(p=>p.id===id);if(!product)return;statusBusy.add(id);const button=[...document.querySelectorAll('[data-action="status"]')].find(b=>b.dataset.id===id);if(button)button.disabled=true;try{await api.save(id,{status:product.status==='active'?'inactive':'active'});toast(product.status==='active'?'已下架，随时可以重新上架。':'已重新上架。');statusBusy.delete(id);if(routeInfo().path==='/profile')await loadRoute();}catch(error){toast(message(error));}finally{statusBusy.delete(id);for(const control of document.querySelectorAll('[data-action="status"]'))if(control.dataset.id===id)control.disabled=false;}}
function filterChanged(){if(routeInfo().path!=='/')navigate('/');else loadHome();}
document.addEventListener('submit',event=>{if(event.target.id==='school-login-form'){event.preventDefault();verifyEmailCode();return;}if(event.target.matches('.search-form')){event.preventDefault();if(submitting||uploading){toast('正在保存或处理照片，请稍等一下。');return;}state.filters.query=String(new FormData(event.target).get('query')||'').trim();filterChanged();}if(event.target.id==='publish-form'){event.preventDefault();saveDraft();}});
document.addEventListener('input',event=>{if(event.target.id==='school-email'){setLoginEmail(event.target.value);return;}if(event.target.id==='school-code'){state.emailLogin.code=event.target.value.replace(/\D/g,'').slice(0,6);event.target.value=state.emailLogin.code;refreshLoginControls();return;}if(event.target.closest('#publish-form')&&event.target.id!=='field-category')captureDraft();});
document.addEventListener('change',event=>{const target=event.target;if(target.matches('[data-filter]')){state.filters[target.dataset.filter]=target.value;filterChanged();}if(target.id==='photo-input')selectPhotos(target);if(target.closest('#publish-form')){if(target.id==='field-category'){captureDraft();$('#category-fields').innerHTML=categoryFields(state.draft);}else{captureDraft();if(target.id==='field-contactType')$('label[for="field-contactValue"]').innerHTML=`${target.value==='phone'?'手机号':'微信号'}<span class="required"> *</span>`;}}});
document.addEventListener('click',async event=>{
if((submitting||uploading||signingOut||state.emailLogin.verifying)&&event.target.closest('a')){event.preventDefault();toast('正在保存或确认登录状态，请稍等一下。');return;}
if(event.target.closest('a[href="#discover"]')){event.preventDefault();$('#discover')?.scrollIntoView({behavior:'smooth'});return;}
if(event.target.closest('.skip-link')){event.preventDefault();$('#main-content')?.focus();return;}
const button=event.target.closest('[data-action]');if(!button){if(event.target.classList.contains('modal-backdrop'))closeModal();return;}const{action,id}=button.dataset;
if((submitting||uploading||signingOut||state.emailLogin.verifying)&&!['close-modal'].includes(action)){event.preventDefault();toast('正在保存或确认登录状态，请稍等一下。');return;}
if(action==='retry-session'){refreshSession();return;}if(action==='retry-route'){loadRoute();return;}if(action==='retry-home'){loadHome();return;}if(action==='close-modal'){closeModal();return;}
if(action==='logout'){confirmLogout();return;}if(action==='confirm-logout'){logout();return;}
if(action==='send-email'){sendEmailCode();return;}if(action==='guest'){becomeGuest();return;}if(action==='confirm-guest'){becomeGuest('guest',true);return;}
if(action==='category'){event.preventDefault();state.filters.category=button.dataset.category;filterChanged();return;}if(action==='chip'){state.filters[button.dataset.filter]=!state.filters[button.dataset.filter];filterChanged();return;}if(action==='clear-filters'){state.filters=defaults();filterChanged();return;}if(action==='load-more'){loadHome(true);return;}
if(action==='favorite'){favorite(id);return;}if(action==='contact'){contact(id);return;}if(action==='status'){changeStatus(id);return;}
if(action==='photo'){const photo=$('#detail-photo');if(photo)photo.src=button.dataset.src;document.querySelectorAll('.thumbnail').forEach(thumb=>{thumb.classList.toggle('selected',thumb===button);thumb.setAttribute('aria-pressed',String(thumb===button));});return;}
if(action==='remove-photo'){captureDraft();const[photo]=state.draft.images.splice(Number(button.dataset.index),1);if(photo?.url.startsWith('blob:'))URL.revokeObjectURL(photo.url);$('#uploaded-images').innerHTML=uploadPreview();return;}
if(action==='preview'){const values=validateDraft();if(!values)return;showModal(`<span class="eyebrow">YOUR GOOD FIND</span><h2>发布前，最后看一眼</h2><img class="preview-photo" src="${esc(state.draft.images[0].url)}" alt="${esc(values.title)}"><h3>${esc(values.title)}</h3><span class="price"><small>¥</small>${money(values.price)}</span><p>${esc(values.condition)} · ${esc(values.campus)} · ${esc(values.location)}</p><p>${esc(values.description).replace(/\n/g,'<br>')}</p><div class="meetup-note">${icon('shield')}商品、昵称与照片公开展示；联系方式仅登录可见。</div><div class="modal-actions"><button class="button secondary" data-action="close-modal">继续编辑</button><button class="button primary" data-action="confirm-publish">${state.draft.id?'确认修改':'确认发布'} ${icon('arrow')}</button></div>`,'商品发布预览');return;}
if(action==='confirm-publish'){closeModal();saveDraft();return;}
if(action==='confirm-retry'){if(state.draft){state.draft.uncertain=false;state.draft.error='';state.draft.notice='';$('#publish-feedback').innerHTML='';toast('可以再次提交，已上传成功的照片会继续使用。');}return;}
if(action==='campus'){showModal(`<span class="modal-emoji">🏫</span><h2>好物，就在你身边</h2><p>西交利物浦大学 · 选择交易校区</p><div class="campus-options">${['','SIP 校区','太仓校区'].map(c=>`<button class="button ${state.filters.campus===c?'primary':'secondary'}" data-action="select-campus" data-campus="${c}">${icon('pin')}${c||'全部校区'}</button>`).join('')}</div>`,'选择校区');return;}
if(action==='select-campus'){state.filters.campus=button.dataset.campus;closeModal();filterChanged();return;}
if(action==='mobile-filters'){showModal(`<h2>挑挑心头好</h2><div class="form-field"><label for="modal-campus">交易校区</label><select id="modal-campus">${campusOptions(state.filters.campus,true)}</select></div><div class="form-field"><label for="modal-condition">商品成色</label><select id="modal-condition">${conditionOptions(state.filters.condition,true)}</select></div><div class="modal-actions"><button class="button primary" data-action="apply-mobile-filters">看看好物 ${icon('arrow')}</button></div>`,'校区和成色筛选');return;}
if(action==='apply-mobile-filters'){state.filters.campus=$('#modal-campus').value;state.filters.condition=$('#modal-condition').value;closeModal();filterChanged();return;}
if(action==='about'){showModal(`<span class="modal-emoji">🍊</span><h2>欢迎来到橘子集</h2><p>为西交利物浦大学 SIP 与太仓校区准备的二手小集市，主打小电器、电瓶车和日常好物。</p><p>学校邮箱验证码登录后可发布、收藏和联系卖家；访客仅可浏览公开商品。邮箱验证不等于在读学籍认证，本平台不提供聊天、订单或支付。</p><p>请与卖家确认信息，在公共区域面交；不提前向陌生人转账。</p><button class="button primary" data-action="close-modal">开始发现好物 ${icon('arrow')}</button>`,'关于橘子集');return;}
if(action==='privacy')showModal(`<span class="modal-emoji">🌿</span><h2>分享好物，照顾隐私</h2><p>商品标题、描述、校区、面交地点、公开昵称和照片可被所有访客查看。请勿在照片或描述中放入证件、住址等敏感信息。</p><p>你填写的微信号或手机号仅已登录用户可查看。登录用户仍可能转发信息，请谨慎选择联系方式。</p><p>你的学校邮箱不会自动成为公开昵称；仅你自己可看到遮罩后的邮箱。发布、收藏与上传图片由网站云端保存；草稿在提交前仅保留于当前页面，刷新后不会恢复。</p><p>联系卖家：打开商品详情并选择“联系卖家”。如需停止公开商品，可在“我的发布”中下架；下架不等于删除照片。</p><button class="button primary" data-action="close-modal">我知道了 ${icon('check')}</button>`,'隐私与联系');
});
document.addEventListener('keydown',event=>{const modal=$('.modal');if(!modal)return;if(event.key==='Escape'){closeModal();return;}if(event.key!=='Tab')return;const focusable=[...modal.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex="0"]')],first=focusable[0],last=focusable.at(-1);if(!first){event.preventDefault();return;}if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===modal)){event.preventDefault();first.focus();}});
window.addEventListener('hashchange',()=>{if(submitting||uploading||signingOut||state.emailLogin.verifying){history.replaceState(null,'',currentRoute||'#/');toast('正在保存或处理照片，请稍等一下。');return;}captureDraft();loadRoute();});
window.addEventListener('beforeunload',event=>{if(submitting||uploading||hasUnsavedDraft()){event.preventDefault();event.returnValue='';}});
await refreshSession();
